mapper.update:
UPDATE tb_credentials
   SET sign_key_id = #{signKeyId},
       sign_key_version = #{signKeyVersion},
       vc_jws_header = #{encodedHeader},
       sign_attempt_no = sign_attempt_no + 1,
       updated_at = #{now}
 WHERE id = #{credentialId}
   AND status = 'ISSUING'
   AND vc_payload IS NULL
   AND sign_attempt_no = #{expectedAttemptNo}
   AND vc_jws_payload = #{encodedPayload}

UPDATE tb_credentials
   SET vc_payload = #{vcPayload},
       vc_hash = #{vcHash},
       updated_at = #{now}
 WHERE id = #{credentialId}
   AND status = 'ISSUING'
   AND vc_payload IS NULL
   AND sign_attempt_no = #{attemptNo}
   AND sign_key_id = #{signKeyId}
   AND sign_key_version = #{signKeyVersion}
   AND vc_jws_header = #{encodedHeader}
   AND vc_jws_payload = #{encodedPayload}
